<script setup lang="ts">import {ref} from 'vue'; const state=ref<'idle'|'loading'|'done'>('idle'); function run(){state.value='loading';setTimeout(()=>state.value='done',700)}</script>
<template><section class="page" data-testid="analysis-page"><h1>分析任务</h1><div class="card"><p v-if="state==='idle'">选择数据批次后开始分析（demo/mock）。</p><p v-else-if="state==='loading'" data-testid="analysis-loading">分析中…</p><p v-else data-testid="analysis-done">分析完成，可前往概览查看结果。</p><button :disabled="state==='loading'" @click="run">开始分析</button></div></section></template>
